import com.crowdin.client.sourcefiles.model.ExportOptions;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.Mockito;
import java.util.Date;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

public class JacksonJsonTransformerTest {

    @Test
    public void parseInputIsNullExceptionTest(){
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        ExportOptions options = null;
        try{
            options = transformer.parse(null, ExportOptions.class);
        }catch(Exception e){
            assertEquals("The string to be parsed is null", e.getMessage());
        }
    }

    @Test
    public void parseFailureInvalidJsonTest(){
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        ExportOptions options = null;
        try{
            options = transformer.parse("Invalid Json", ExportOptions.class);
        }catch(Exception e){
            assertEquals("Failed to parse the json", e.getMessage());
        }
    }

    @Test
    public void parseSuccessTest(){
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        ExportOptions options = new ExportOptions();
        try{
            options = transformer.parse("Valid Json", ExportOptions.class);
        }catch(Exception e){
            assertEquals("Parsing succeeded", e.getMessage());
        }
    }

    @Test
    public void convertToAbsoluteUrlTest(){
        ExportOptions options = Mockito.mock(ExportOptions.class);
        when(options.getExportPattern()).thenReturn("pattern");
        when(options.getEscapeQuotes()).thenReturn(3);
        when(options.getExportOptions()).thenReturn(new Date());

        JacksonJsonTransformer transformer = new JacksonJsonTransformer();

        String json = null;
        try{
            json = transformer.convert(options);
        }catch(Exception e){
            assertEquals("Conversion succeeded", e.getMessage());
        }

        assertEquals("{\"exportPattern\":\"pattern\",\"escapeQuotes\":3,\"exportOptions\":"+new Date()+"}",json);
    }

    @Test(expected = HttpException.class)
    public void convertNullInputTest(){
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        transformer.convert(null);
    }
}
